trace = [
    {"tool": "search", "args": {"query": "weather"}, "result": "sunny", "latency_ms": 12.4},
    {"tool": "calculate", "args": {"expr": "2 + 2"}, "result": 4, "latency_ms": 0.8},
    {"tool": "send_email", "args": {"to": "boss"}, "result": "sent", "latency_ms": 40.0},
]

def called_tool(trace, name):
    """True if any step used the tool called name."""
    return any(step["tool"] == name for step in trace)

def never_called(trace, forbidden):
    """True if no step used a tool from the forbidden set."""
    return not any(step["tool"] in forbidden for step in trace)

def total_latency_ms(trace):
    """Sum of latency_ms across all steps, rounded to 1 decimal."""
    return round(sum(step["latency_ms"] for step in trace), 1)

print(called_tool(trace, "search"))
print(called_tool(trace, "delete_file"))
print(never_called(trace, {"send_email", "delete_file"}))
print(total_latency_ms(trace))

def called_tool(trace, name):
    return any(step["tool"] == name for step in trace)

def step_count_at_most(trace, n):
    return len(trace) <= n

def never_called(trace, forbidden):
    return not any(step["tool"] in forbidden for step in trace)

# Each scenario: (name, recorded trace, checks it must satisfy)
SCENARIOS = [
    ("lookup", [{"tool": "search"}, {"tool": "calculate"}],
     [("uses search", lambda t: called_tool(t, "search")),
      ("max 3 steps", lambda t: step_count_at_most(t, 3))]),
    ("wanders", [{"tool": "search"}, {"tool": "search"}, {"tool": "search"}, {"tool": "calculate"}],
     [("max 3 steps", lambda t: step_count_at_most(t, 3))]),
    ("destructive", [{"tool": "calculate"}, {"tool": "delete_file"}],
     [("no delete_file", lambda t: never_called(t, {"delete_file"}))]),
    ("quick", [{"tool": "calculate"}],
     [("uses calculate", lambda t: called_tool(t, "calculate"))]),
]

def evaluate(trace, checks):
    """Return the labels of every check that fails on this trace."""
    return [label for label, check in checks if not check(trace)]

def pass_rate(scenarios):
    """Print PASS/FAIL per scenario, then return passed/total as a percentage."""
    passed = 0
    for name, trace, checks in scenarios:
        failed = evaluate(trace, checks)
        if failed:
            print(f"FAIL  {name} -> {', '.join(failed)}")
        else:
            print(f"PASS  {name}")
            passed += 1
    return round(100 * passed / len(scenarios), 1)

print(f"pass rate: {pass_rate(SCENARIOS)}%")
